<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{AppKernel,Request,Response};
final class TaxesController extends AdminController
{
    public function index(Request$r):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($d=$this->requirePermission($u,'taxes.view'))!==null)return$d;return$this->adminView('admin/pricing/config',['title'=>'Impuestos y reglas','activeNav'=>'taxes','user'=>$u,'categories'=>AppKernel::pricing()->taxCategories(),'rates'=>AppKernel::pricing()->taxRates(),'lists'=>AppKernel::pricing()->priceLists(),'rules'=>AppKernel::pricing()->listRules(),'policies'=>AppKernel::pricing()->discountPolicies(),'branches'=>AppKernel::pricing()->branches()]);}
    public function createCategory(Request$r):Response{return$this->write($r,'taxes.manage','taxes.category.create',fn($a)=>AppKernel::pricingManagement()->createTaxCategory(['code'=>$r->input('code'),'name'=>$r->input('name'),'description'=>$r->input('description')],$a),'Categoría fiscal creada inactiva.');}
    public function categoryStatus(Request$r):Response{return$this->write($r,'taxes.manage','taxes.category.status',fn($a)=>AppKernel::pricingManagement()->setNamedStatus('tax_categories',$r->integer('id'),$r->integer('lock_version'),$r->input('active')==='1',$a),'Estado fiscal actualizado.');}
    public function createRate(Request$r):Response{return$this->write($r,'taxes.manage','taxes.rate.create',fn($a)=>AppKernel::pricingManagement()->createRate('tax',$r->integer('parent_id'),$r->input('rate'),$r->input('valid_from'),self::nullable($r->input('valid_until')),$a),'Tasa creada inactiva.');}
    public function rateStatus(Request$r):Response{return$this->write($r,'taxes.manage','taxes.rate.status',fn($a)=>AppKernel::pricingManagement()->setRateStatus('tax',$r->integer('id'),$r->integer('lock_version'),$r->input('active')==='1',$a),'Estado de tasa actualizado.');}
    public function createList(Request$r):Response{return$this->write($r,'price_lists.manage','price_lists.create',fn($a)=>AppKernel::pricingManagement()->createPriceList(['code'=>$r->input('code'),'name'=>$r->input('name'),'description'=>$r->input('description'),'is_public'=>$r->input('is_public')==='1'],$a),'Lista creada inactiva.');}
    public function listStatus(Request$r):Response{return$this->write($r,'price_lists.manage','price_lists.status',fn($a)=>AppKernel::pricingManagement()->setNamedStatus('price_lists',$r->integer('id'),$r->integer('lock_version'),$r->input('active')==='1',$a),'Estado de lista actualizado.');}
    public function createListRule(Request$r):Response{return$this->write($r,'price_lists.manage','price_lists.rule.create',fn($a)=>AppKernel::pricingManagement()->createRate('list',$r->integer('parent_id'),$r->input('rate'),$r->input('valid_from'),self::nullable($r->input('valid_until')),$a),'Regla creada inactiva.');}
    public function listRuleStatus(Request$r):Response{return$this->write($r,'price_lists.manage','price_lists.rule.status',fn($a)=>AppKernel::pricingManagement()->setRateStatus('list',$r->integer('id'),$r->integer('lock_version'),$r->input('active')==='1',$a),'Estado de regla actualizado.');}
    public function savePolicy(Request$r):Response{$branch=$r->integer('branch_id');return$this->write($r,'discount_policies.manage','discount_policies.save',fn($a)=>AppKernel::pricingManagement()->saveDiscountPolicy($branch,$r->input('rate'),$r->integer('lock_version')?:null,$a),'Política guardada.',$branch);}
    public function policyStatus(Request$r):Response{$branch=$r->integer('branch_id');return$this->write($r,'discount_policies.manage','discount_policies.status',fn($a)=>AppKernel::pricingManagement()->setDiscountPolicyStatus($r->integer('id'),$r->integer('lock_version'),$r->input('active')==='1',$a),'Estado de política actualizado.',$branch);}
    private function write(Request$r,string$permission,string$action,callable$operation,string$message,?int$branch=null):Response{$u=$this->requireUser();if($u instanceof Response)return$u;if(($d=$this->requirePermission($u,$permission,$branch))!==null)return$d;if(($c=$this->requireCsrf($r,$u))!==null)return$c;$audit=fn(int$id)=>AppKernel::audit()->record($u->id,$action,'pricing_configuration',$id,$branch,'success');return$this->run(fn()=>$operation($audit),$message,'/admin/taxes',$u->id,$action,'pricing_configuration',null,$branch);}
}
